import scala.collection.mutable
import scala.concurrent.{Future, Promise, ExecutionContext}
import scala.util.{Try, Success, Failure}
import java.util.concurrent.atomic.{AtomicInteger, AtomicReference, AtomicBoolean}
import java.util.concurrent.{ConcurrentHashMap, ScheduledExecutorService, Executors, TimeUnit}

sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

class CircuitBreaker(threshold: Int, resetTimeout: Long) {
  private val state = new AtomicReference[CircuitState](Closed)
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicReference[Long](0L)

  def currentState: CircuitState = state.get()

  def recordSuccess(): Unit = {
    failureCount.set(0)
    state.set(Closed)
  }

  def recordFailure(): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (count >= threshold) {
      state.set(Open)
    }
  }

  def allowRequest(): Boolean = state.get() match {
    case Closed => true
    case Open =>
      if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeout) {
        state.compareAndSet(Open, HalfOpen)
        true
      } else false
    case HalfOpen => true
  }
}

trait MessageHandler {
  def handle(msg: ChatMessage): Unit
  def shutdown(): Unit
}

case class ChatMessage(roomId: String, userId: String, content: String, timestamp: Long)

class ChatRoom(val roomId: String)(implicit ec: ExecutionContext) {
  private val subscribers = new ConcurrentHashMap[String, MessageHandler]()
  private val messageBuffer = new AtomicReference[List[ChatMessage]](Nil)
  private val isActive = new AtomicBoolean(true)

  def subscribe(userId: String, handler: MessageHandler): Unit = {
    if (isActive.get()) {
      subscribers.put(userId, handler)
    }
  }

  def unsubscribe(userId: String): Unit = {
    subscribers.remove(userId)
  }

  def broadcast(msg: ChatMessage): Unit = {
    if (isActive.get()) {
      val current = messageBuffer.get()
      messageBuffer.set(msg :: current)
      subscribers.forEach { (_, handler) =>
        handler.handle(msg)
      }
    }
  }

  def drainAndClose(): List[ChatMessage] = {
    isActive.set(false)
    val messages = messageBuffer.getAndSet(Nil)
    subscribers.forEach { (uid, handler) =>
      handler.shutdown()
      subscribers.remove(uid)
    }
    messages
  }
}

class ChatServer(implicit ec: ExecutionContext) {
  private val rooms = new ConcurrentHashMap[String, ChatRoom]()
  private val circuitBreakers = new ConcurrentHashMap[String, CircuitBreaker]()
  private val scheduler: ScheduledExecutorService = Executors.newScheduledThreadPool(2)
  private val closedRoomIds = ConcurrentHashMap.newKeySet[String]()

  def getOrCreateRoom(roomId: String): ChatRoom = {
    rooms.computeIfAbsent(roomId, _ => new ChatRoom(roomId))
  }

  def getCircuitBreaker(roomId: String): CircuitBreaker = {
    circuitBreakers.computeIfAbsent(roomId, _ => new CircuitBreaker(5, 30000L))
  }

  def sendMessage(msg: ChatMessage): Future[Boolean] = Future {
    val cb = getCircuitBreaker(msg.roomId)
    if (!cb.allowRequest()) {
      false
    } else {
      try {
        val room = getOrCreateRoom(msg.roomId)
        room.broadcast(msg)
        cb.recordSuccess()
        true
      } catch {
        case e: Exception =>
          cb.recordFailure()
          false
      }
    }
  }

  def closeRoom(roomId: String): Future[List[ChatMessage]] = Future {
    val room = rooms.remove(roomId)
    if (room != null) {
      closedRoomIds.add(roomId)
      val messages = room.drainAndClose()
      // Schedule cleanup of metadata only - no reference to old room
      scheduleMetadataCleanup(roomId)
      messages
    } else Nil
  }

  private def scheduleMetadataCleanup(roomId: String): Unit = {
    // Only clean up metadata (circuit breaker state), no room reference held
    scheduler.schedule(new Runnable {
      override def run(): Unit = {
        circuitBreakers.remove(roomId)
        closedRoomIds.remove(roomId)
      }
    }, 5, TimeUnit.SECONDS)
  }

  def joinRoom(roomId: String, userId: String, handler: MessageHandler): Unit = {
    if (!closedRoomIds.contains(roomId)) {
      val room = getOrCreateRoom(roomId)
      room.subscribe(userId, handler)
    }
  }

  def leaveRoom(roomId: String, userId: String): Unit = {
    val room = rooms.get(roomId)
    if (room != null) {
      room.unsubscribe(userId)
    }
  }

  def shutdown(): Unit = {
    scheduler.shutdown()
    rooms.forEach { (_, room) => room.drainAndClose() }
    rooms.clear()
    closedRoomIds.clear()
  }
}
